    descrizione: "Lancio per parapendio a Lüsen (Luson, Trentino-Alto Adige), a 1603 m s.l.m. Esposizione SW/S. Atterraggio mappato a Lüsen (Luson) (856 m), a 1.7 km dal decollo; dislivello di volo ~749 m. very good for relax-pilots who want some guidance (school). XC also possible, but not very often large distances. soaring termico within the valle is the main game. Used by Papillon school, you should ask them prior to using the lancio. Private ground. Before launching here ask in the bar / hotel Tulper for permission. Valutazione della community: 3/6.",
